import{_ as a,o as e,c as s,a5 as i}from"./chunks/framework.DJo0M80U.js";const k=JSON.parse('{"title":"The Little Book of C 教程（多语言）","description":"The Little Book of C 中英双语动手课程入口：从第一个程序到可交付 C 小工具。","frontmatter":{"title":"The Little Book of C 教程（多语言）","date":"2026-07-04T00:00:00.000Z","categories":["C 教程"],"tags":["C","Little Book of C","多语言"],"sidebarWeight":0,"description":"The Little Book of C 中英双语动手课程入口：从第一个程序到可交付 C 小工具。"},"headers":[],"relativePath":"posts/c教程/README.md","filePath":"posts/c教程/README.md","lastUpdated":1790163617000}'),l={name:"posts/c教程/README.md"};function d(n,t,o,h,r,p){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="the-little-book-of-c-·-c-语言小书" tabindex="-1">The Little Book of C · C 语言小书 <a class="header-anchor" href="#the-little-book-of-c-·-c-语言小书" aria-label="Permalink to &quot;The Little Book of C · C 语言小书&quot;">​</a></h1><blockquote><p>基于 Duc-Tam Nguyen 的 <a href="https://little-book-of.github.io/c/books/en-US/book.html" target="_blank" rel="noreferrer">The Little Book of C</a>（<a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noreferrer">CC BY-NC-SA 4.0</a>）</p></blockquote><p>这套教程不只适合通读概念。你会从 <code>printf</code> 开始，逐步完成计算器、手动内存管理、小型数据结构、文件日志工具、Makefile、Mini Shell、调试修复、可移植多线程程序，最后交付一个可以构建、运行、测试、打包和说明取舍的 C 小项目。</p><p>完成后，你应该能把 C 代码从“能跑”推进到“可维护、可调试、可交付”：</p><ul><li>设计一个小型命令行工具，拆分 <code>.c</code> / <code>.h</code> 文件，并用 Makefile 稳定构建。</li><li>解释栈、堆、指针、生命周期、深浅拷贝和未定义行为对程序正确性的影响。</li><li>用警告、断言、调试器、内存检查和代码审查清单定位问题。</li><li>处理文件 I/O、错误码、命令行参数、系统调用、进程、管道和信号。</li><li>为最终项目留下可展示证据：源码、构建命令、运行输出、测试记录、调试记录、README 和版本标签。</li></ul><p>这份证据可以用于作品集、代码面试复盘、系统编程入门项目，或后续学习操作系统、数据库、编译器、嵌入式开发时的基础练习。它不能保证职位或录用结果，但能证明你已经动手完成过 C 项目的核心工程流程。</p><h2 id="固定练习工作区" tabindex="-1">固定练习工作区 <a class="header-anchor" href="#固定练习工作区" aria-label="Permalink to &quot;固定练习工作区&quot;">​</a></h2><p>所有练习统一放在同一个工作区，避免命令输出散落在教程目录里。</p><p>macOS / Linux:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/c-course-labs</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/c-course-labs</span></span></code></pre></div><p>Windows PowerShell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">New-Item</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ItemType Directory </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Force </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\c-course-labs&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Set-Location</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\c-course-labs&quot;</span></span></code></pre></div><p>每个练习单独创建目录，例如 <code>020-calculator</code>、<code>060-makefile-lab</code>、<code>100-tinynotes</code>。每章完成后，把运行命令、关键输出、遇到的问题和下一步改进写进该目录下的 <code>evidence.md</code>。</p><h2 id="编译标准选择" tabindex="-1">编译标准选择 <a class="header-anchor" href="#编译标准选择" aria-label="Permalink to &quot;编译标准选择&quot;">​</a></h2><p>默认练习建议使用更稳妥的 C17：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -std=c17</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Wall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Wextra</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Wpedantic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span></code></pre></div><p>课程中涉及 C23 的章节会把它作为现代能力或可选升级来练。GCC 文档说明 C23 可用 <code>-std=c23</code> 选择，Clang 的 C 支持页把 C23 标为部分支持；因此做跨编译器练习时，先用 C17 保证主线能跑，再用 C23 对照新特性和兼容性。</p><ul><li>Source: <a href="https://gcc.gnu.org/onlinedocs/gcc/Standards.html" target="_blank" rel="noreferrer">GCC language standards</a></li><li>Source: <a href="https://clang.llvm.org/c_status.html" target="_blank" rel="noreferrer">Clang C language status</a></li></ul><h2 id="选择语言" tabindex="-1">选择语言 <a class="header-anchor" href="#选择语言" aria-label="Permalink to &quot;选择语言&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语言</th><th>目录</th><th>说明</th></tr></thead><tbody><tr><td><strong>中文</strong></td><td><a href="./zh-CN/README">zh-CN 教程总览</a></td><td>适合中文跟练，保留原书代码并补充课程化学习路径</td></tr><tr><td><strong>English</strong></td><td><a href="./en-US/README">en-US Index</a></td><td>English path with the same hands-on contract</td></tr></tbody></table><h2 id="章节对照" tabindex="-1">章节对照 <a class="header-anchor" href="#章节对照" aria-label="Permalink to &quot;章节对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>英文章节</th><th>中文章节</th></tr></thead><tbody><tr><td>01-Getting Started</td><td>01-入门</td></tr><tr><td>02-Language Basics</td><td>02-语言基础</td></tr><tr><td>03-Working with Memory</td><td>03-内存</td></tr><tr><td>04-Structuring Data</td><td>04-数据结构</td></tr><tr><td>05-Input Output and Files</td><td>05-输入输出与文件</td></tr><tr><td>06-Compilation and Build</td><td>06-编译与构建</td></tr><tr><td>07-Working Close to the System</td><td>07-贴近系统</td></tr><tr><td>08-Debugging Testing Profiling</td><td>08-调试测试与 profiling</td></tr><tr><td>09-Portable and Modern C</td><td>09-可移植与现代 C</td></tr><tr><td>10-Building Real Projects</td><td>10-真实项目</td></tr><tr><td>11-Epilogue</td><td>11-结语</td></tr></tbody></table><p>每篇文章顶部可切换 <strong>中文 / English</strong>（<code>alternateZh</code> / <code>alternateEn</code>）。</p>`,23)])])}const g=a(l,[["render",d]]);export{k as __pageData,g as default};
